SET statement_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

DROP TABLE IF EXISTS "salas" CASCADE;
CREATE TABLE "salas" (
    "id_sala" TEXT,
    "descrip" TEXT
);


DROP TABLE IF EXISTS "juzgados" CASCADE;
CREATE TABLE "juzgados" (
    "id_juzgado" TEXT,
    "descrip" TEXT
);


DROP TABLE IF EXISTS "delitos" CASCADE;
CREATE TABLE "delitos" (
    "id_delito" TEXT,
    "descrip" TEXT
);


DROP TABLE IF EXISTS "usuarios" CASCADE;
CREATE TABLE "usuarios" (
    "nom_usu" TEXT,
    "contra" TEXT,
    "nombre" TEXT,
    "nivel" BIGINT,
    "idjuzgado" TEXT,
    "id_ubica" TEXT,
    "descrip" TEXT,
    "folio" TEXT
);


DROP TABLE IF EXISTS "apelaciones_penal" CASCADE;
CREATE TABLE "apelaciones_penal" (
    "folio" BIGINT,
    "cu" TEXT,
    "juzgado" TEXT,
    "proceso" TEXT,
    "anio" TEXT,
    "acum" TEXT,
    "fecha" TEXT,
    "hora" TEXT,
    "delito" TEXT,
    "tipo_apela" TEXT,
    "sala" TEXT,
    "anexos" TEXT,
    "nombre" TEXT,
    "estatus" TEXT,
    "resolucion" TEXT,
    "proceado" DOUBLE PRECISION,
    "mp" DOUBLE PRECISION,
    "defensa" DOUBLE PRECISION,
    "agraviado" DOUBLE PRECISION,
    "tipo" TEXT,
    "sello" TEXT,
    "recusacion" TEXT,
    "casacion" DOUBLE PRECISION,
    "presidente" TEXT,
    "relator" TEXT,
    "tercero" TEXT
);


